  "It asks to:": "要求する権限：",
  "It closed before it opened. Try again.": "開く前に閉じてしまいました。もう一度試してください。",
  "It couldn’t start on this Mac.": "このMacで起動できませんでした。",
  "It ended before it could write up the build.": "ビルドのまとめを書く前に終了しました。",
  "It finishes its own setup the first time it opens.": "初めて開いたときに、自分でセットアップを完了します。",
  "It hasn't started yet.": "まだ始まっていません。",
  "It installs when you relaunch; Genex tells you when it's ready.":
    "再起動するとインストールされます。準備ができたらGenexがお知らせします。",
  "It is on and stays on: its new code runs as soon as it loads, and each of its tools asks you again before it runs.":
    "オンのままになります。新しいコードは読み込まれるとすぐに実行され、各ツールは実行前にもう一度確認します。",
  "It isn’t on this Mac any more. Install it again.": "このMacにはもうありません。もう一度インストールしてください。",
  "It keeps downloading if you go back.": "戻ってもダウンロードは続きます。",
  "It keeps your scripts as files in this game's folder and tells Genex which Studio is this game's.":
    "スクリプトをこのゲームのフォルダーにファイルとして保存し、どのStudioがこのゲームのものかをGenexに伝えます。",
  "It kept getting this wrong, so it stopped to save your credits.":
    "何度もうまくいかなかったので、クレジットを節約するために止めました。",
  "It leaves Play and genex.games and goes back to drafts. The direct link still works, and plays and likes stay if it’s published again.":
    "「プレイ」とgenex.gamesから消えて、下書きに戻ります。直接リンクはそのまま使えて、もう一度公開すればプレイ数といいねも残ります。",
  "It may need the setup scripts its packages came with, which didn’t run.":
    "パッケージ付属のセットアップスクリプトが必要かもしれません（まだ実行されていません）。",
  "It merged this part's work without a reviewer's verdict. The reviewers score parts that build in steps; this one was built in one session.":
    "レビュアーの判定なしで、このパートの作業を取り込みました。レビュアーが採点するのはステップごとにつくるパートで、このパートは1回のセッションでつくられました。",
  "It merges into your build when the lead integrates this part.":
    "メインエージェントがこのパートを統合すると、ビルドに追加されます。",
  "It needs macOS {version} or later.": "macOS {version}以降が必要です。",
  "It never uses password managers, Windows Settings, password prompts or Genex.":
    "パスワードマネージャー、Windowsの設定、パスワード入力画面、Genexは決して操作しません。",
  "It ran into an error": "エラーが発生しました",
  "It runs at Genex's moments: {steps}; those steps don't ask you first.":
    "Genexの次のタイミングで実行されます：{steps}。これらのステップは事前に確認しません。",
  "It runs with your access: Genex doesn't sandbox its code.":
    "あなたの権限で動作します。Genexはこのコードをサンドボックス化しません。",
  "It runs, but no reviewer compared it with the game you had.":
    "動作はしますが、レビュアーは前のゲームと比較していません。",
  "It shows up here as soon as it runs.": "動くようになったら、すぐここに表示されます。",
  "It starts off: turn it on in Plugins; each of its tools asks you before it runs.":
    "最初はオフです。「プラグイン」でオンにしてください。各ツールは実行前に確認します。",
  "It stopped before this was fixed.": "直る前に止まりました。",
  "It treats this as a {kind} game — that decides the controls it drives before every look, and who reviews it.":
    "これを「{kind}」タイプのゲームとして扱います。これで、毎回の確認の前に使う操作と、誰がレビューするかが決まります。",
  "It turns on when installed: agents in all your games can use it from your next message.":
    "インストールするとオンになります。次のメッセージから、すべてのゲームのエージェントが使えます。",
  "It was paused before it could write up the build.": "ビルドのまとめを書く前に一時停止されました。",
  "It's no longer there.": "もう存在しません。",
  "It's switched on in Studio's settings. Studio answers once a place is open: open one in Studio, or press New Roblox game.":
    "Studioの設定でオンになっています。プレイスが開くとStudioが応答します。Studioでプレイスを開くか、「新しいRobloxゲーム」を押してください。",
  "It's switched on in Studio's settings. Studio answers once it has finished opening.":
    "Studioの設定でオンになっています。Studioが開ききると応答します。",
  "Its author no longer shares it.": "作者が共有をやめました。",
  "Its code runs on your computer like an app you install. It isn't sandboxed.":
    "このコードは、インストールしたアプリと同じようにコンピューター上で動きます。サンドボックス化されていません。",
  "Its creator hasn’t shared this game’s project yet, so it can’t be remixed.":
    "作者がまだこのゲームのプロジェクトを共有していないので、リミックスできません。",
  "Its files are in your game folder, waiting for the lead to use them.":
    "ファイルはゲームフォルダーにあり、メインエージェントが使うのを待っています。",
  "Its own scene": "独自のシーン",
  "Its packages aren’t installed yet — “{install}” runs on one press.":
    "パッケージがまだインストールされていません。「{install}」はワンクリックで実行できます。",
  "Its packages aren’t installed yet.": "パッケージがまだインストールされていません。",
  "Its project didn’t go, so no one can remix it yet.":
    "プロジェクトが送れなかったので、まだ誰もリミックスできません。",
  "Its project is too big to remix: Genex keeps up to 5 GB and 5,000 files.":
    "プロジェクトが大きすぎてリミックスできません。Genex に置けるのは 5 GB・5,000 ファイルまでです。",
  "Its session failed before it delivered anything.": "何も提出しないうちにセッションが失敗しました。",
  "Its source is your own repository: run genex make-remixable in the game’s folder to allow remixing.":
    "ソースはあなた自身のリポジトリにあります。リミックスを許可するには、ゲームのフォルダーでgenex make-remixableを実行してください。",
  "Its steps at Genex's moments changed (hooks, observers, locks, folders or harness tools), so it wasn't reloaded: load it again with Load local plugin… to review them":
    "Genexの各タイミングでこのプラグインが行う処理（フック、オブザーバー、ロック、フォルダー、Harnessツール）が変わったため、再読み込みしませんでした。確認するには「ローカルプラグインを読み込む…」でもう一度読み込んでください",
  "Its time ran out before a final look at your game.": "ゲームを最後に確認する前に時間切れになりました。",
  "Its time ran out before this was fixed.": "直す前に時間切れになりました。",
